--
-- Name: transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transactions (
    completed_at timestamp with time zone,
    completed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    state text NOT NULL,
    tags jsonb DEFAULT '{}'::jsonb NOT NULL,
    tenant_id uuid NOT NULL,
    params jsonb DEFAULT '{}'::jsonb NOT NULL,
    schema_version integer,
    apply_task_id uuid,
    reserved_at timestamp with time zone,
    reserved_by text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT transactions_check CHECK ((((state = ANY (ARRAY['open'::text, 'previewing'::text, 'previewed'::text, 'commit-reserved'::text, 'committing'::text])) AND (completed_at IS NULL)) OR ((state = ANY (ARRAY['aborted'::text, 'failed'::text, 'failed-committed'::text, 'committed'::text])) AND (completed_at IS NOT NULL)))),
    CONSTRAINT transactions_reserved_check CHECK (((state <> 'commit-reserved'::text) OR ((reserved_at IS NOT NULL) AND (reserved_by IS NOT NULL))))
);


