    name text NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    type text DEFAULT 'user'::text NOT NULL,
    auth_origin text,
    auth_config_hash text,
    external_id text,
    display_name text,
    avatar_url text,
    password_hash text,
    capabilities jsonb,
    base_capabilities jsonb,
    capability_trie jsonb NOT NULL,
    base_capability_trie jsonb NOT NULL,
    CONSTRAINT users_auth_method_check CHECK (((type <> 'user'::text) OR ((type = 'user'::text) AND ((auth_origin IS NULL) OR (password_hash IS NULL)))))
);


